var EXEC={ "bucket-trace": function(inp){var m=inp.m,b=[];
for(var i=0;i<m;i++)b.push([]);
inp.keys.forEach(function(k){var h;
if(typeof k==='number')h=((k%m)+m)%m;
else{h=0;for(var j=0;j<k.length;j++)h+=k.charCodeAt(j);h%=m;}
b[h].push(k);});
return {buckets:b};} };
var MK={ "bucket-trace": function(rnd){var m=rnd()<0.5?5:7,keys=[],n=6+((rnd()*5)|0),pool='abcdefgh';
for(var i=0;i<n;i++){var w='',L=2+((rnd()*3)|0);
for(var j=0;j<L;j++)w+=pool[(rnd()*pool.length)|0];
keys.push(w);}
return {m:m,keys:keys};} };
var TRACE_GROUP="hashing";
var TRACE_TITLES={ "bucket-trace": "hash-to-bucket mapping" };
var P1={ "bucket-trace": "Hash the keys {keys} into {m} buckets with chaining, using the toy hash h = (sum of char codes) mod {m}. The drill asks for every bucket's final contents. Compute each key's char sum by hand — it's the only arithmetic in hashing, and doing it manually builds respect for what real hash functions do at speed." };
var P2={ "bucket-trace": "Collisions are normal: keys sharing a bucket simply chain together, and lookup walks the chain. The load factor here is {nkeys}/{m} = {lf} — comfortably under 1, so chains stay short. Notice which keys collide: with a weak hash like a char sum, anagrams ALWAYS collide — a real reason production hashes mix bits instead of adding them." };
var P3={ "bucket-trace": "Bucket contents: {buckets}. Check yours bucket by bucket. Then ask: which bucket is longest, and what would happen to lookup cost if the load factor hit 100?" };
var PYPROG={ "bucket-trace": "TRACE_INPUT = {input}\nm, keys = TRACE_INPUT['m'], TRACE_INPUT['keys']\nbuckets = [[] for _ in range(m)]\nfor k in keys:\n    h = sum(map(ord, k)) % m   # toy hash: char-code sum mod m\n    buckets[h].append(k)       # chaining: append to the bucket\nfor i, b in enumerate(buckets):\n    print(i, b)\n" };
var SIG=true;
var GEN_SRC="signature-line";
var GEN_DISCLAIMER="Signature-line generated drill — deterministic and Signature-framed, not an archive record. Seeded archive records are the authoritative entries.";
function fmt(t,obj){return String(t).replace(/\{([a-zA-Z0-9_]+)\}/g,function(m,k){var v=obj[k];if(v===undefined)return m;return (v&&typeof v==='object')?JSON.stringify(v):String(v);});}
function traceCtx(input,expected){
  var ctx={};
  Object.keys(input).forEach(function(k){ctx[k]=input[k];});
  Object.keys(expected).forEach(function(k){ctx[k]=expected[k];});
  if(input.ops)ctx.nops=input.ops.length;
  if(input.keys){ctx.nkeys=input.keys.length;ctx.lf=input.keys.length+'/'+input.m;}
  if(input.m&&input.m.length&&typeof input.m[0]!=='string')ctx.n=input.m.length;
  return ctx;
}
function genComplexity(rnd,seed){
  var o=pick(OPS,rnd);
  var desc='This drill tests one fact cold: the time complexity of '+o[0]+' on '+( /^[aeiou]/i.test(NAME)?'an ':'a' )+NAME+'. '
    +'Cover the answer, say it out loud, then check yourself — interviewers expect this bound instantly, and fluency here compounds across every other record in this archive.'
    +'\n\n'+o[3]
    +'\n\n'+'The bound: '+o[1]+' — '+o[2]+' If you said it before reading this far, it is yours; if not, work the operation it belongs to and come back.';
  var r={
    id:PREFIX+String(seed).padStart(6,'0'),
    title:'Complexity drill: '+o[0]+' — '+NAME,
    description:desc,
    ladder:2,group:'complexity',
    operations:[{op:o[0],complexity:o[1],note:o[2]}],
    complexity_notes:o[0]+': '+o[1]+'. '+o[2],
    method:'complexity-drill',
    answer:{op:o[0],complexity:o[1]},
    src:GEN_SRC,last_verified:'2026-10-19'
  };
  if(SIG){r.creation_mode='SIGNATURE-GENERATED';}
  else{r.sample=true;}
  r.disclaimer=GEN_DISCLAIMER;
  return r;
}
function genTrace(rnd,seed){
  var kind="bucket-trace";
  var input=MK[kind](rnd);
  var expected=EXEC[kind](input);
  var ctx=traceCtx(input,expected);
  var desc=fmt(P1[kind],ctx)+'\n\n'+fmt(P2[kind],ctx)+'\n\n'+fmt(P3[kind],ctx);
  var prog=PYPROG[kind].split('@@INPUT@@').join(JSON.stringify(input));
  var r={
    id:PREFIX+String(seed).padStart(6,'0'),
    title:'Trace drill: '+TRACE_TITLES[kind]+' — '+NAME,
    description:desc,
    ladder:2,group:TRACE_GROUP,
    method:kind,
    test:{input:input,expected:expected},
    program:prog,language:'python',
    complexity_notes:'Drill answer computed by the reference implementation; validate() recomputes it independently.',
    src:GEN_SRC,last_verified:'2026-10-19'
  };
  if(SIG){r.creation_mode='SIGNATURE-GENERATED';}
  else{r.sample=true;}
  r.disclaimer=GEN_DISCLAIMER;
  return r;
}
function frameSig(r){
  r.description="Signature line: the hash table as a deterministic protocol. In the Signature idiom a hash table is a sealed key lane — every key mapped by a published hash function to a published slot, collisions resolved by a published discipline, the same key landing in the same slot on every run. Where the public record below describes the conventional hash table, the Signature edition pins its behavior: the hash function is fixed and auditable, the load-factor threshold is published, resizing replays deterministically, and every operation carries its exact cost in the open."+'\n\n'+r.description+'\n\n'+"That is the Signature line on hash tables: the key always finds its slot, and the mapping never drifts. The facts above are the standard facts — average O(1) operations, chaining vs open addressing, load-factor resizing — sealed inside a deterministic protocol so a lookup computed once replays identically, everywhere.";
  return r;
}
function generate(seed,opts,rnd){
  opts=opts||{};rnd=rnd||prng(seed);
  if(seed>=1&&seed<=ARCHIVE.length){
    return JSON.parse(JSON.stringify(ARCHIVE[seed-1]));
  }
  var g=opts.group&&FIELDS.indexOf(opts.group)>=0?opts.group:null;
  var rec=rnd()<0.5?genComplexity(rnd,seed):genTrace(rnd,seed);
  if(g)rec.group=g;
  if(SIG)frameSig(rec);
  return rec;
}
function sjson(v){return JSON.stringify(v);}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  if(!new RegExp('^'+PREFIX.replace(/-/g,'\\-')+'\\d{6}$').test(r.id||''))e.push('id');
  if(FIELDS.indexOf(r.group)<0)e.push('group');
  if(typeof r.title!=='string'||!r.title.length)e.push('title');
  if(typeof r.description!=='string'||r.description.length<200)e.push('description');
  if(r.src!==GEN_SRC&&r.src!=='reference-authored'&&r.src!=='signature-line')e.push('src');
  if(r.method==='complexity-drill'){
    var hit=null;
    for(var i=0;i<OPS.length;i++)if(OPS[i][0]===r.answer.op)hit=OPS[i];
    if(!hit)e.push('unknown op');
    else if(r.answer.complexity!==hit[1])e.push('complexity mismatch');
  }else if(r.method&&EXEC[r.method]){
    var got;
    try{got=EXEC[r.method](r.test.input);}catch(x){e.push('exec threw');}
    if(got&&sjson(got)!==sjson(r.test.expected))e.push('trace mismatch');
  }else if(!r.method){
    if(!(r.ladder>=1&&r.ladder<=3))e.push('ladder');
  }else{
    e.push('method');
  }
  return {ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  var seen={};(sample||[]).forEach(function(s){if(s&&s.t)seen[s.t]=1;});
  if(rec&&seen[rec.title])return {ok:false,errors:['duplicate title in archive sample']};
  return {ok:true,errors:[]};
}
var gen={version:'jahdb-hash-table-signature-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('hash-table-signature',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
